-- Frozen unversioned store from 444b999; synthetic test keys.
BEGIN TRANSACTION;
CREATE TABLE checkpoint_schedule(
    log_id TEXT PRIMARY KEY,
    checkpoint_hash TEXT NOT NULL,
    next_checkpoint_at REAL NOT NULL
);
INSERT INTO "checkpoint_schedule" VALUES('123e4567-e89b-42d3-a456-426614174000','47c8a4e6e723a0d40a049d4f6369140c04381bbd4869d9b4ba15b96153abe407',2000000000.0);
CREATE TABLE checkpoints(
    log_id TEXT NOT NULL,
    idx INTEGER NOT NULL,
    count INTEGER NOT NULL,
    checkpoint_hash TEXT NOT NULL,
    envelope BLOB NOT NULL,
    state TEXT NOT NULL,
    UNIQUE(log_id, idx),
    UNIQUE(log_id, checkpoint_hash)
);
INSERT INTO "checkpoints" VALUES('123e4567-e89b-42d3-a456-426614174000',0,1,'47c8a4e6e723a0d40a049d4f6369140c04381bbd4869d9b4ba15b96153abe407',X'','accepted');
INSERT INTO "checkpoints" VALUES('123e4567-e89b-42d3-a456-426614174000',1,2,'00d2bcdbb98089557ec62fc302535ad5eee0d11ef7e0b1d3a7b0603e5e3ba83e',X'','pending');
CREATE TABLE heads(
    log_id TEXT PRIMARY KEY,
    count INTEGER NOT NULL,
    head_hash TEXT NOT NULL,
    sealed INTEGER NOT NULL DEFAULT 0
);
INSERT INTO "heads" VALUES('123e4567-e89b-42d3-a456-426614174000',2,'bd453dd7c9155233bfdcccbeacdf17e456a9e7e47dce8317ae9a044da133dcf1',2);
CREATE TABLE manifests(
    log_id TEXT PRIMARY KEY,
    manifest_hash TEXT NOT NULL UNIQUE,
    envelope BLOB NOT NULL
);
INSERT INTO "manifests" VALUES('123e4567-e89b-42d3-a456-426614174000','19bf8e0c623a772a103dd7a4deaaa38bb6f9ea0c8ce99504900117cb376cf768',X'');
CREATE TABLE outbox(
    log_id TEXT PRIMARY KEY,
    checkpoint_hash TEXT NOT NULL,
    from_seq INTEGER NOT NULL,
    to_seq INTEGER NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    next_attempt_at REAL NOT NULL DEFAULT 0
);
INSERT INTO "outbox" VALUES('123e4567-e89b-42d3-a456-426614174000','00d2bcdbb98089557ec62fc302535ad5eee0d11ef7e0b1d3a7b0603e5e3ba83e',2,2,3,2000000001.0);
CREATE TABLE receipts(
    checkpoint_hash TEXT PRIMARY KEY,
    envelope BLOB NOT NULL
);
INSERT INTO "receipts" VALUES('47c8a4e6e723a0d40a049d4f6369140c04381bbd4869d9b4ba15b96153abe407',X'');
CREATE TABLE records(
    log_id TEXT NOT NULL,
    seq INTEGER NOT NULL,
    event_id TEXT NOT NULL,
    request_digest TEXT NOT NULL,
    record_hash TEXT NOT NULL,
    envelope BLOB NOT NULL,
    UNIQUE(log_id, seq),
    UNIQUE(log_id, event_id)
